      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "The second hidden layer has 10 neurons receiving 1000 inputs, requiring 1000 × 10 = 10,000 weight parameters.",
      "evidence": "Weight matrix size = (outputs of previous layer) × (neurons in this layer).",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 4,
      "claim": "The second hidden layer also needs 10 bias parameters.",
      "evidence": "One bias per neuron.",
      "weight": 0.10,
      "depends_on": []
    },
    {
      "id": 5,
      "claim": "The output layer maps 10 activations to a single scalar, needing 10 × 1 = 10 weight parameters and 1 bias parameter.",
      "evidence": "Same rule as above for the final affine transformation.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 6,
      "claim": "Summing all parameters: 100,000 + 1,000 + 10,000 + 10 + 10 + 1 = 111,021.",
      "evidence": "Arithmetic addition of the counts from steps 1‑5.",
      "weight": 1.0,
      "depends_on": [1, 2, 3, 4, 5]
    }
  ],
